        hist_idx_hist_value = hist_idx_hist_value + 1;
        repeat (1) @(posedge default_clock);
        #1;
        hist_value[hist_idx_hist_value] = {{56{1'b0}}, top_value};
        hist_idx_hist_value = hist_idx_hist_value + 1;
        seq_ok = 1'b1;
        seq_bad = 0;
        for (wi = 0; wi < 256; wi = wi + 1) begin
            if (hist_value[hist_idx_hist_value - 1 - wi] !== hist_value[hist_idx_hist_value - 1 - wi - 256]) begin
                seq_ok = 1'b0;
                seq_bad = wi;
            end
        end
        checks = checks + 1;
        if (!seq_ok) begin fails = fails + 1; $display("CHECK period_256#0 FAIL (seq_self top_value idx=%0d", seq_bad); end else $display("CHECK period_256#0 PASS");

        // 收尾约定：运行护栏按这一行判红绿（不是退出码：$finish 恒返回 0）。
        $display("RESULT: checks=%0d fails=%0d", checks, fails);
        if (fails != 0) $fatal(1, "TB failed");
        $finish;
    end

`ifdef DUMP_VCD
    initial begin
        $dumpfile("tb_counter_simple_example.vcd");
        $dumpvars(0, tb_counter_simple_example);
    end
`endif

endmodule
